class Solution {
public:
    bool canConstruct(string note, string mag) {
        int cnt[26] = {0};
        for (char c : mag) cnt[c - 'a']++;
        for (char c : note) if (--cnt[c - 'a'] < 0) return false;
        return true;
    }
};
